                    <span class="debug-value" id="debugDT">0</span>
                </div>
                <div class="debug-row">
                    <span class="debug-label">ST:</span>
                    <span class="debug-value" id="debugST">0</span>
                </div>
            </div>

            <div class="debug-section">
                <div class="debug-title">Stack</div>
                <div id="debugStack"></div>
            </div>

            <div class="debug-section">
                <div class="debug-title">Current Instruction</div>
                <div id="debugInstruction"></div>
            </div>
