    <script>
        // CHIP-8 Emulator
        class CHIP8 {
            constructor() {
                // Memory: 4KB (0x000 - 0xFFF)
                this.memory = new Uint8Array(4096);

                // Registers: V0-VF (16 8-bit registers)
                this.registers = new Uint8Array(16);

                // Index register (16-bit)
                this.I = 0;

                // Program counter
                this.PC = 0x200;

                // Stack for subroutine calls
                this.stack = [];

                // Timers (count down at 60 Hz)
                this.delayTimer = 0;
                this.soundTimer = 0;

                // Display: 64x32 pixels
                this.display = new Uint8Array(64 * 32);

                // Keypad state: 16 keys (0-F)
                this.keys = new Uint8Array(16);

                // Load font set at 0x050
                this.loadFonts();

                // Running state
                this.running = false;
                this.paused = false;

                // Current opcode
                this.currentOpcode = 0;
            }

            loadFonts() {
                // CHIP-8 font set (5 bytes per character, 16 characters 0-F)
                const fonts = [
                    0xF0, 0x90, 0x90, 0x90, 0xF0, // 0
                    0x20, 0x60, 0x20, 0x20, 0x70, // 1
                    0xF0, 0x10, 0xF0, 0x80, 0xF0, // 2
                    0xF0, 0x10, 0xF0, 0x10, 0xF0, // 3
                    0x90, 0x90, 0xF0, 0x10, 0x10, // 4
                    0xF0, 0x80, 0xF0, 0x10, 0xF0, // 5
                    0xF0, 0x80, 0xF0, 0x90, 0xF0, // 6
                    0xF0, 0x10, 0x20, 0x40, 0x40, // 7
                    0xF0, 0x90, 0xF0, 0x90, 0xF0, // 8
                    0xF0, 0x90, 0xF0, 0x10, 0xF0, // 9
                    0xF0, 0x90, 0xF0, 0x90, 0x90, // A
                    0xE0, 0x90, 0xE0, 0x90, 0xE0, // B
                    0xF0, 0x80, 0x80, 0x80, 0xF0, // C
                    0xE0, 0x90, 0x90, 0x90, 0xE0, // D
                    0xF0, 0x80, 0xF0, 0x80, 0xF0, // E
                    0xF0, 0x80, 0xF0, 0x80, 0x80  // F
                ];

                for (let i = 0; i < fonts.length; i++) {
                    this.memory[0x50 + i] = fonts[i];
                }
            }

            loadROM(data) {
                for (let i = 0; i < data.length; i++) {
                    this.memory[0x200 + i] = data[i];
                }
            }

            reset() {
                this.registers.fill(0);
                this.I = 0;
                this.PC = 0x200;
                this.stack = [];
                this.delayTimer = 0;
                this.soundTimer = 0;
                this.display.fill(0);
                this.keys.fill(0);
                this.running = false;
                this.paused = false;
                this.currentOpcode = 0;
            }

            fetch() {
                const high = this.memory[this.PC];
                const low = this.memory[this.PC + 1];
                this.currentOpcode = (high << 8) | low;
                return this.currentOpcode;
            }

            decode() {
                return this.currentOpcode;
            }

            execute() {
                const opcode = this.currentOpcode;
                const x = (opcode >> 8) & 0xF;
                const y = (opcode >> 4) & 0xF;
                const n = opcode & 0xF;
                const kk = opcode & 0xFF;
                const nnn = opcode & 0xFFF;

                switch (opcode & 0xF000) {
                    case 0x0000:
                        if (opcode === 0x00E0) {
                            // 00E0: Clear display
                            this.display.fill(0);
                        } else if (opcode === 0x00EE) {
                            // 00EE: Return from subroutine
                            this.PC = this.stack.pop();
                        }
                        break;

                    case 0x1000:
                        // 1nnn: Jump to address nnn
                        this.PC = nnn;
                        return;

                    case 0x2000:
                        // 2nnn: Call subroutine at nnn
                        this.stack.push(this.PC);
                        this.PC = nnn;
                        return;

                    case 0x3000:
                        // 3xkk: Skip next instruction if Vx == kk
                        if (this.registers[x] === kk) {
                            this.PC += 2;
                        }
                        break;

                    case 0x4000:
                        // 4xkk: Skip next instruction if Vx != kk
                        if (this.registers[x] !== kk) {
                            this.PC += 2;
                        }
                        break;

                    case 0x5000:
                        // 5xy0: Skip next instruction if Vx == Vy
                        if (this.registers[x] === this.registers[y]) {
                            this.PC += 2;
                        }
                        break;

                    case 0x6000:
                        // 6xkk: Set Vx = kk
                        this.registers[x] = kk;
                        break;

                    case 0x7000:
                        // 7xkk: Add kk to Vx
                        this.registers[x] = (this.registers[x] + kk) & 0xFF;
                        break;

                    case 0x8000:
                        switch (opcode & 0x000F) {
                            case 0x0:
                                // 8xy0: Set Vx = Vy
                                this.registers[x] = this.registers[y];
                                break;
                            case 0x1:
                                // 8xy1: Set Vx = Vx | Vy
                                this.registers[x] |= this.registers[y];
                                break;
                            case 0x2:
                                // 8xy2: Set Vx = Vx & Vy
                                this.registers[x] &= this.registers[y];
                                break;
                            case 0x3:
                                // 8xy3: Set Vx = Vx ^ Vy
                                this.registers[x] ^= this.registers[y];
                                break;
                            case 0x4:
                                // 8xy4: Add Vy to Vx, set VF = carry
                                const sum = this.registers[x] + this.registers[y];
                                this.registers[0xF] = sum > 0xFF ? 1 : 0;
                                this.registers[x] = sum & 0xFF;
                                break;
                            case 0x5:
                                // 8xy5: Subtract Vy from Vx, set VF = NOT borrow
                                this.registers[0xF] = this.registers[x] >= this.registers[y] ? 1 : 0;
                                this.registers[x] = (this.registers[x] - this.registers[y]) & 0xFF;
                                break;
                            case 0x6:
                                // 8xy6: Set Vx = Vy >> 1, set VF = LSB of Vy
                                this.registers[0xF] = this.registers[y] & 1;
                                this.registers[x] = this.registers[y] >> 1;
                                break;
                            case 0x7:
                                // 8xy7: Set Vx = Vy - Vx, set VF = NOT borrow
                                this.registers[0xF] = this.registers[y] >= this.registers[x] ? 1 : 0;
                                this.registers[x] = (this.registers[y] - this.registers[x]) & 0xFF;
                                break;
                            case 0xE:
                                // 8xyE: Set Vx = Vy << 1, set VF = MSB of Vy
                                this.registers[0xF] = (this.registers[y] >> 7) & 1;
                                this.registers[x] = (this.registers[y] << 1) & 0xFF;
                                break;
                        }
                        break;

                    case 0x9000:
                        // 9xy0: Skip next instruction if Vx != Vy
                        if (this.registers[x] !== this.registers[y]) {
                            this.PC += 2;
                        }
                        break;

                    case 0xA000:
                        // Annn: Set I = nnn
                        this.I = nnn;
                        break;

                    case 0xB000:
                        // Bnnn: Jump to address nnn + V0
                        this.PC = nnn + this.registers[0];
                        return;

                    case 0xC000:
                        // Cxkk: Set Vx = random byte & kk
                        this.registers[x] = (Math.floor(Math.random() * 256)) & kk;
                        break;

                    case 0xD000:
                        // Dxyn: Draw sprite at (Vx, Vy) with height n
                        this.drawSprite(this.registers[x], this.registers[y], n);
                        break;

                    case 0xE000:
                        switch (opcode & 0x00FF) {
                            case 0x9E:
                                // Ex9E: Skip next instruction if key Vx is pressed
                                if (this.keys[this.registers[x]]) {
                                    this.PC += 2;
                                }
                                break;
                            case 0xA1:
                                // ExA1: Skip next instruction if key Vx is NOT pressed
                                if (!this.keys[this.registers[x]]) {
                                    this.PC += 2;
                                }
                                break;
                        }
                        break;

                    case 0xF000:
                        switch (opcode & 0x00FF) {
                            case 0x07:
                                // Fx07: Set Vx = delay timer
                                this.registers[x] = this.delayTimer;
                                break;
                            case 0x0A:
                                // Fx0A: Wait for a key press, store the value in Vx
                                let keyPressed = false;
                                for (let i = 0; i < 16; i++) {
                                    if (this.keys[i]) {
                                        this.registers[x] = i;
                                        keyPressed = true;
                                        break;
                                    }
                                }
                                if (!keyPressed) {
                                    this.PC -= 2; // Retry this instruction
                                }
                                break;
                            case 0x15:
                                // Fx15: Set delay timer = Vx
                                this.delayTimer = this.registers[x];
                                break;
                            case 0x18:
                                // Fx18: Set sound timer = Vx
                                this.soundTimer = this.registers[x];
                                break;
                            case 0x1E:
                                // Fx1E: Add Vx to I
                                this.I = (this.I + this.registers[x]) & 0xFFFF;
                                break;
                            case 0x29:
                                // Fx29: Set I = location of sprite for digit Vx
                                this.I = 0x50 + (this.registers[x] * 5);
                                break;
                            case 0x33:
                                // Fx33: Store BCD representation of Vx at I, I+1, I+2
                                const val = this.registers[x];
                                this.memory[this.I] = Math.floor(val / 100);
                                this.memory[this.I + 1] = Math.floor((val % 100) / 10);
                                this.memory[this.I + 2] = val % 10;
                                break;
                            case 0x55:
                                // Fx55: Store registers V0 to Vx in memory starting at I
                                for (let i = 0; i <= x; i++) {
                                    this.memory[this.I + i] = this.registers[i];
                                }
                                break;
                            case 0x65:
                                // Fx65: Read registers V0 to Vx from memory starting at I
                                for (let i = 0; i <= x; i++) {
                                    this.registers[i] = this.memory[this.I + i];
                                }
                                break;
                        }
                        break;
                }

                this.PC += 2;
            }

            drawSprite(x, y, height) {
                this.registers[0xF] = 0;

                for (let row = 0; row < height; row++) {
                    const spriteByte = this.memory[this.I + row];

                    for (let col = 0; col < 8; col++) {
                        const pixelSet = (spriteByte >> (7 - col)) & 1;

                        if (pixelSet) {
                            const px = (x + col) % 64;
                            const py = (y + row) % 32;
                            const index = py * 64 + px;

                            if (this.display[index]) {
                                this.registers[0xF] = 1; // Collision
                            }

                            this.display[index] ^= 1;
                        }
                    }
                }
            }

            updateTimers() {
                if (this.delayTimer > 0) this.delayTimer--;
                if (this.soundTimer > 0) this.soundTimer--;
            }

            step() {
                if (!this.running) return;
                this.fetch();
                this.execute();
            }

            getInstructionMnemonic() {
                const opcode = this.currentOpcode;
                const x = (opcode >> 8) & 0xF;
                const y = (opcode >> 4) & 0xF;
                const n = opcode & 0xF;
                const kk = opcode & 0xFF;
                const nnn = opcode & 0xFFF;

                switch (opcode & 0xF000) {
                    case 0x0000:
                        if (opcode === 0x00E0) return "CLS";
                        if (opcode === 0x00EE) return "RET";
                        return `SYS ${nnn.toString(16).toUpperCase().padStart(3, '0')}`;
                    case 0x1000: return `JP ${nnn.toString(16).toUpperCase().padStart(3, '0')}`;
                    case 0x2000: return `CALL ${nnn.toString(16).toUpperCase().padStart(3, '0')}`;
                    case 0x3000: return `SE V${x.toString(16).toUpperCase()}, ${kk.toString(16).toUpperCase().padStart(2, '0')}`;
                    case 0x4000: return `SNE V${x.toString(16).toUpperCase()}, ${kk.toString(16).toUpperCase().padStart(2, '0')}`;
                    case 0x5000: return `SE V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
                    case 0x6000: return `LD V${x.toString(16).toUpperCase()}, ${kk.toString(16).toUpperCase().padStart(2, '0')}`;
                    case 0x7000: return `ADD V${x.toString(16).toUpperCase()}, ${kk.toString(16).toUpperCase().padStart(2, '0')}`;
                    case 0x8000:
                        switch (opcode & 0xF) {
                            case 0x0: return `LD V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
                            case 0x1: return `OR V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
                            case 0x2: return `AND V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
                            case 0x3: return `XOR V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
                            case 0x4: return `ADD V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
                            case 0x5: return `SUB V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
                            case 0x6: return `SHR V${x.toString(16).toUpperCase()}`;
                            case 0x7: return `SUBN V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
                            case 0xE: return `SHL V${x.toString(16).toUpperCase()}`;
                        }
                        break;
                    case 0x9000: return `SNE V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
                    case 0xA000: return `LD I, ${nnn.toString(16).toUpperCase().padStart(3, '0')}`;
                    case 0xB000: return `JP V0, ${nnn.toString(16).toUpperCase().padStart(3, '0')}`;
                    case 0xC000: return `RND V${x.toString(16).toUpperCase()}, ${kk.toString(16).toUpperCase().padStart(2, '0')}`;
                    case 0xD000: return `DRW V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}, ${n}`;
                    case 0xE000:
                        if ((opcode & 0xFF) === 0x9E) return `SKP V${x.toString(16).toUpperCase()}`;
                        if ((opcode & 0xFF) === 0xA1) return `SKNP V${x.toString(16).toUpperCase()}`;
                        break;
                    case 0xF000:
                        switch (opcode & 0xFF) {
                            case 0x07: return `LD V${x.toString(16).toUpperCase()}, DT`;
                            case 0x0A: return `LD V${x.toString(16).toUpperCase()}, K`;
                            case 0x15: return `LD DT, V${x.toString(16).toUpperCase()}`;
                            case 0x18: return `LD ST, V${x.toString(16).toUpperCase()}`;
                            case 0x1E: return `ADD I, V${x.toString(16).toUpperCase()}`;
                            case 0x29: return `LD F, V${x.toString(16).toUpperCase()}`;
                            case 0x33: return `LD B, V${x.toString(16).toUpperCase()}`;
                            case 0x55: return `LD [I], V${x.toString(16).toUpperCase()}`;
                            case 0x65: return `LD V${x.toString(16).toUpperCase()}, [I]`;
                        }
                        break;
                }
                return `${opcode.toString(16).toUpperCase().padStart(4, '0')}`;
            }
        }

        // UI Controller
        class EmulatorUI {
            constructor() {
                this.chip8 = new CHIP8();
                this.canvas = document.getElementById('display');
                this.ctx = this.canvas.getContext('2d');
                this.scale = 10;
                this.instructionsPerFrame = 10;
                this.frameCount = 0;
                this.lastTimerUpdate = Date.now();

                this.setupCanvas();
                this.setupKeypad();
                this.setupControls();
                this.setupKeyboardInput();
                this.updateDebugger();
                this.render();
            }

            setupCanvas() {
                this.canvas.width = 64 * this.scale;
                this.canvas.height = 32 * this.scale;
            }

            setupKeypad() {
                const keypadContainer = document.getElementById('keypad');
                const keyMap = [
                    ['1', '2', '3', 'C'],
                    ['4', '5', '6', 'D'],
                    ['7', '8', '9', 'E'],
                    ['A', '0', 'B', 'F']
                ];

                keypadContainer.innerHTML = '';

                keyMap.forEach((row, rowIdx) => {
                    row.forEach((key, colIdx) => {
                        const keyNum = rowIdx * 4 + colIdx;
                        const btn = document.createElement('div');
                        btn.className = 'key';
                        btn.textContent = key;
                        btn.dataset.key = keyNum;

                        btn.addEventListener('mousedown', () => {
                            this.chip8.keys[keyNum] = 1;
                            btn.classList.add('pressed');
                        });

                        btn.addEventListener('mouseup', () => {
                            this.chip8.keys[keyNum] = 0;
                            btn.classList.remove('pressed');
                        });

                        btn.addEventListener('mouseleave', () => {
                            this.chip8.keys[keyNum] = 0;
                            btn.classList.remove('pressed');
                        });

                        keypadContainer.appendChild(btn);
                    });
                });

